const projectGeo = (lon: number, lat: number): Point => ({
  x: MAP_CENTER.x + lon * RAD * MAP_SCALE,
  y: MAP_CENTER.y - lat * RAD * MAP_SCALE,
});

const PROJECTED_HUBS = HUBS.map((hub) => projectGeo(hub.lon, hub.lat));

const mulberry32 = (seed: number) => {
  let value = seed >>> 0;
  return () => {
    value += 0x6d2b79f5;
    let result = value;
    result = Math.imul(result ^ (result >>> 15), result | 1);
    result ^= result + Math.imul(result ^ (result >>> 7), result | 61);
    return ((result ^ (result >>> 14)) >>> 0) / 4294967296;
  };
};

const gaussianPair = (random: () => number): [number, number] => {
  const u = Math.max(1e-6, random());
  const v = random();
  const radius = Math.sqrt(-2 * Math.log(u));
  return [radius * Math.cos(2 * Math.PI * v), radius * Math.sin(2 * Math.PI * v)];
};

let cachedLandPath: Path2D | null = null;
let cachedBorderPath: Path2D | null = null;
let cachedCityLights: CityLight[] | null = null;
let cachedCityBaseCanvas: HTMLCanvasElement | null = null;

const getPaths = () => {
  cachedLandPath ??= new Path2D(LAND_PATH);
  cachedBorderPath ??= new Path2D(BORDER_PATH);
  return {land: cachedLandPath, borders: cachedBorderPath};
};

const buildCityLights = (
  context: CanvasRenderingContext2D,
  land: Path2D,
): CityLight[] => {
  if (cachedCityLights) {
    return cachedCityLights;
  }

  const random = mulberry32(0x7ac31e5);
  const lights: CityLight[] = [];
  const add = (x: number, y: number, intensity: number) => {
    if (!context.isPointInPath(land, x, y)) {
      return;
    }
    lights.push({
      x,
      y,
      radius: 0.42 + random() * 1.18 + intensity * 0.38,
      phase: random() * Math.PI * 2,
      rate: 0.014 + random() * 0.032,
      intensity: 0.2 + intensity * 0.8,
    });
  };

  for (let index = 0; index < 2200; index++) {
    const lon = -178 + random() * 356;
    const lat = -54 + random() * 126;
    const point = projectGeo(lon, lat);
    add(point.x, point.y, 0.16 + random() * 0.32);
  }

  HUBS.forEach((hub, hubIndex) => {
    const center = PROJECTED_HUBS[hubIndex];
    const count = Math.round(40 + hub.importance * 72);
    for (let index = 0; index < count; index++) {
      const [gx, gy] = gaussianPair(random);
      const spreadX = 18 + 28 * hub.importance;
      const spreadY = 10 + 17 * hub.importance;
      add(
        center.x + gx * spreadX,
        center.y + gy * spreadY,
        0.46 + random() * 0.45,
      );
    }
  });

  cachedCityLights = lights;
  return lights;
};

const getCityBaseCanvas = (cityLights: CityLight[]) => {
  if (cachedCityBaseCanvas) {
    return cachedCityBaseCanvas;
  }

  const canvas = document.createElement('canvas');
  canvas.width = DESIGN_WIDTH / 2;
  canvas.height = DESIGN_HEIGHT / 2;
  const context = canvas.getContext('2d');
  if (!context) {
    return canvas;
  }

  context.setTransform(0.5, 0, 0, 0.5, 0, 0);
  context.globalCompositeOperation = 'lighter';
  for (let index = 0; index < cityLights.length; index++) {
    const light = cityLights[index];
    const alpha = 0.12 + light.intensity * 0.22;
    context.beginPath();
    context.arc(light.x, light.y, light.radius * 0.9, 0, Math.PI * 2);
    context.fillStyle = `rgba(95, 208, 255, ${alpha})`;
    context.fill();

    if (index % 19 === 0) {
      const radius = 4 + light.intensity * 7;
      const glow = context.createRadialGradient(
        light.x,
        light.y,
        0,
        light.x,
        light.y,
        radius,
      );
      glow.addColorStop(0, `rgba(191, 239, 255, ${alpha * 0.7})`);
      glow.addColorStop(0.35, `rgba(46, 166, 255, ${alpha * 0.18})`);
      glow.addColorStop(1, 'rgba(0, 76, 212, 0)');
      context.fillStyle = glow;
      context.fillRect(light.x - radius, light.y - radius, radius * 2, radius * 2);
    }
  }

  cachedCityBaseCanvas = canvas;
  return canvas;
};

const cameraState = (frame: number, durationInFrames: number) => {
  const progress = Math.max(0, Math.min(1, frame / Math.max(1, durationInFrames - 1)));
  return {
    progress,
    angle: (-7.4 + progress * 14.8) * RAD,
    screenX: 985 - progress * 82,
    screenY: 548,
    scaleX: 1.035,
    scaleY: 0.93,
  };
};

const transformPoint = (
  point: Point,
  camera: ReturnType<typeof cameraState>,
): Point => {
  const dx = (point.x - MAP_CENTER.x) * camera.scaleX;
  const dy = (point.y - MAP_CENTER.y) * camera.scaleY;
  const cosine = Math.cos(camera.angle);
  const sine = Math.sin(camera.angle);
  return {
    x: camera.screenX + dx * cosine - dy * sine,
    y: camera.screenY + dx * sine + dy * cosine,
  };
};

const applyMapTransform = (
  context: CanvasRenderingContext2D,
  camera: ReturnType<typeof cameraState>,
) => {
  context.translate(camera.screenX, camera.screenY);
  context.rotate(camera.angle);
  context.scale(camera.scaleX, camera.scaleY);
  context.translate(-MAP_CENTER.x, -MAP_CENTER.y);
};

const drawGlow = (
  context: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  alpha: number,
  coreRadius = 2.1,
) => {
  const gradient = context.createRadialGradient(x, y, 0, x, y, radius);
  gradient.addColorStop(0, `rgba(245, 253, 255, ${Math.min(1, alpha * 1.7)})`);
  gradient.addColorStop(0.09, `rgba(173, 231, 255, ${alpha})`);
  gradient.addColorStop(0.31, `rgba(56, 175, 255, ${alpha * 0.32})`);
  gradient.addColorStop(0.64, `rgba(16, 106, 224, ${alpha * 0.11})`);
  gradient.addColorStop(1, 'rgba(0, 72, 190, 0)');
  context.fillStyle = gradient;
  context.fillRect(x - radius, y - radius, radius * 2, radius * 2);

  context.beginPath();
  context.arc(x, y, coreRadius, 0, Math.PI * 2);
  context.fillStyle = `rgba(240, 252, 255, ${Math.min(1, alpha * 1.8)})`;
  context.fill();
};

const quadraticPoint = (a: Point, control: Point, b: Point, progress: number) => {
  const inverse = 1 - progress;
  return {
    x:
      inverse * inverse * a.x +
      2 * inverse * progress * control.x +
      progress * progress * b.x,
    y:
      inverse * inverse * a.y +
      2 * inverse * progress * control.y +
      progress * progress * b.y,
  };
};

const drawBackground = (context: CanvasRenderingContext2D) => {
  const base = context.createLinearGradient(0, 0, 0, DESIGN_HEIGHT);
  base.addColorStop(0, '#01070c');
  base.addColorStop(0.38, '#03101a');
  base.addColorStop(0.76, '#020a12');
  base.addColorStop(1, '#000306');
  context.fillStyle = base;
  context.fillRect(0, 0, DESIGN_WIDTH, DESIGN_HEIGHT);

  const atmosphere = context.createRadialGradient(980, 560, 50, 980, 560, 990);
  atmosphere.addColorStop(0, 'rgba(11, 73, 117, 0.24)');
  atmosphere.addColorStop(0.34, 'rgba(7, 48, 82, 0.13)');
  atmosphere.addColorStop(0.72, 'rgba(1, 19, 33, 0.035)');
  atmosphere.addColorStop(1, 'rgba(0, 0, 0, 0)');
  context.fillStyle = atmosphere;
  context.fillRect(0, 0, DESIGN_WIDTH, DESIGN_HEIGHT);
};

const drawMap = (
  context: CanvasRenderingContext2D,
  frame: number,
  camera: ReturnType<typeof cameraState>,
  land: Path2D,
  borders: Path2D,
  cityLights: CityLight[],
  cityBaseCanvas: HTMLCanvasElement,
) => {
  context.save();
  applyMapTransform(context, camera);

  context.fillStyle = 'rgba(4, 19, 31, 0.96)';
  context.fill(land);

  context.save();
  context.globalCompositeOperation = 'lighter';
  context.shadowColor = 'rgba(48, 170, 255, 0.32)';
  context.shadowBlur = 14;
  context.strokeStyle = 'rgba(92, 194, 238, 0.21)';
  context.lineWidth = 1.05;
  context.stroke(land);
  context.shadowBlur = 0;
  context.strokeStyle = 'rgba(88, 178, 222, 0.035)';
  context.lineWidth = 0.62;
  context.stroke(borders);
  context.restore();

  context.save();
  context.clip(land);
  context.globalCompositeOperation = 'lighter';
  context.drawImage(cityBaseCanvas, 0, 0, DESIGN_WIDTH, DESIGN_HEIGHT);

  for (let index = 0; index < cityLights.length; index += 4) {
    const light = cityLights[index];
    const sine = 0.5 + 0.5 * Math.sin(frame * light.rate + light.phase);
    const twinkle = 0.28 + 0.72 * Math.pow(sine, 5);
    const alpha = (0.18 + twinkle * 0.74) * light.intensity;
    context.beginPath();
    context.arc(light.x, light.y, light.radius * (0.84 + twinkle * 0.28), 0, Math.PI * 2);
    context.fillStyle = `rgba(115, 220, 255, ${alpha})`;
    context.fill();

    if (index % 13 === 0 && twinkle > 0.6) {
      const radius = 7 + light.intensity * 13;
      const gradient = context.createRadialGradient(
        light.x,
        light.y,
        0,
        light.x,
        light.y,
        radius,
      );
      gradient.addColorStop(0, `rgba(224, 250, 255, ${alpha * 0.75})`);
      gradient.addColorStop(0.35, `rgba(53, 183, 255, ${alpha * 0.2})`);
      gradient.addColorStop(1, 'rgba(0, 90, 220, 0)');
      context.fillStyle = gradient;
      context.fillRect(light.x - radius, light.y - radius, radius * 2, radius * 2);
    }
  }
  context.restore();
  context.restore();
};

const drawRoute = (
  context: CanvasRenderingContext2D,
  route: Route,
  routeIndex: number,
  transformedHubs: Point[],
  frame: number,
  fps: number,
) => {
  const start = transformedHubs[route.from];
  const end = transformedHubs[route.to];
  const distance = Math.hypot(end.x - start.x, end.y - start.y);
  const control: Point = {
    x: (start.x + end.x) * 0.5 + route.bend * Math.min(160, distance * 0.16),
    y:
      Math.min(start.y, end.y) -
      Math.min(300, 28 + distance * route.lift * 0.82),
  };

  const path = new Path2D();
  path.moveTo(start.x, start.y);
  path.quadraticCurveTo(control.x, control.y, end.x, end.y);

  context.save();
  context.globalCompositeOperation = 'lighter';
  context.lineCap = 'round';

  context.shadowColor = 'rgba(52, 177, 255, 0.25)';
  context.shadowBlur = 19;
  context.strokeStyle = 'rgba(41, 151, 231, 0.105)';
  context.lineWidth = 5.2;
  context.stroke(path);

  context.shadowBlur = 7;
  context.strokeStyle = 'rgba(111, 211, 255, 0.22)';
  context.lineWidth = 2.1;
  context.stroke(path);

  context.shadowBlur = 0;
  context.strokeStyle = `rgba(207, 241, 255, ${0.36 + (routeIndex % 4) * 0.035})`;
  context.lineWidth = 0.86;
  context.stroke(path);

  const travel = ((frame / (fps * route.duration) + route.phase) % 1 + 1) % 1;
  const endpointFade = Math.min(1, travel / 0.085, (1 - travel) / 0.085);
  const head = quadraticPoint(start, control, end, travel);
  const headAlpha = endpointFade * (0.72 + 0.18 * Math.sin(frame * 0.045 + routeIndex));

  for (let trailIndex = 4; trailIndex >= 1; trailIndex--) {
    const trailProgress = travel - trailIndex * 0.012;
    if (trailProgress <= 0) {
      continue;
    }
    const trail = quadraticPoint(start, control, end, trailProgress);
    const trailAlpha = headAlpha * (1 - trailIndex / 5) * 0.36;
    context.beginPath();
    context.arc(trail.x, trail.y, 0.7 + (4 - trailIndex) * 0.18, 0, Math.PI * 2);
    context.fillStyle = `rgba(147, 224, 255, ${trailAlpha})`;
    context.fill();
  }

  drawGlow(
    context,
    head.x,
    head.y,
    13 + (routeIndex % 3) * 3.4,
    headAlpha,
    1.45 + (routeIndex % 2) * 0.45,
  );
  context.restore();
};

const drawHub = (
  context: CanvasRenderingContext2D,
  hub: Hub,
  point: Point,
  frame: number,
  hubIndex: number,
) => {
  const wave = 0.5 + 0.5 * Math.sin(frame * (0.026 + (hubIndex % 5) * 0.0027) + hub.phase);
  const pulse = 0.48 + 0.52 * Math.pow(wave, 2.4);
  const alpha = (0.5 + 0.43 * pulse) * (0.58 + hub.importance * 0.42);
  const radius = 24 + hub.importance * 36 + pulse * 10;

  context.save();
  context.globalCompositeOperation = 'lighter';

  if (hub.importance > 0.82) {
    const rayWidth = 105 + hub.importance * 135;
    const ray = context.createLinearGradient(point.x - rayWidth, point.y, point.x + rayWidth, point.y);
    ray.addColorStop(0, 'rgba(26, 124, 232, 0)');
    ray.addColorStop(0.35, `rgba(69, 182, 255, ${alpha * 0.035})`);
    ray.addColorStop(0.5, `rgba(181, 232, 255, ${alpha * 0.19})`);
    ray.addColorStop(0.65, `rgba(69, 182, 255, ${alpha * 0.035})`);
    ray.addColorStop(1, 'rgba(26, 124, 232, 0)');
    context.fillStyle = ray;
    context.fillRect(point.x - rayWidth, point.y - 1.6, rayWidth * 2, 3.2);
  }

  drawGlow(context, point.x, point.y, radius, alpha, 2 + hub.importance * 1.5);

  const ringAlpha = 0.16 + pulse * 0.18;
  context.beginPath();
  context.arc(point.x, point.y, 7 + pulse * 4.2, 0, Math.PI * 2);
  context.strokeStyle = `rgba(123, 219, 255, ${ringAlpha})`;
  context.lineWidth = 0.9;
  context.stroke();
  context.restore();
};

const drawVignette = (context: CanvasRenderingContext2D) => {
  const vignette = context.createRadialGradient(960, 530, 430, 960, 530, 1120);
  vignette.addColorStop(0, 'rgba(0, 0, 0, 0)');
  vignette.addColorStop(0.64, 'rgba(0, 2, 7, 0.08)');
  vignette.addColorStop(1, 'rgba(0, 0, 0, 0.72)');
  context.fillStyle = vignette;
  context.fillRect(0, 0, DESIGN_WIDTH, DESIGN_HEIGHT);
};

const NetworkCanvas: React.FC = () => {
  const frame = useCurrentFrame();
  const {fps, width, height, durationInFrames} = useVideoConfig();
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useLayoutEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }
    const context = canvas.getContext('2d');
    if (!context) {
      return;
    }

    context.setTransform(1, 0, 0, 1, 0, 0);
    context.clearRect(0, 0, width, height);
    context.setTransform(width / DESIGN_WIDTH, 0, 0, height / DESIGN_HEIGHT, 0, 0);

    const {land, borders} = getPaths();
    const cityLights = buildCityLights(context, land);
    const cityBaseCanvas = getCityBaseCanvas(cityLights);
    const camera = cameraState(frame, durationInFrames);
    const transformedHubs = PROJECTED_HUBS.map((point) => transformPoint(point, camera));

    drawBackground(context);
    drawMap(context, frame, camera, land, borders, cityLights, cityBaseCanvas);

    for (let index = 0; index < ROUTES.length; index++) {
      drawRoute(context, ROUTES[index], index, transformedHubs, frame, fps);
    }
    for (let index = 0; index < HUBS.length; index++) {
      drawHub(context, HUBS[index], transformedHubs[index], frame, index);
    }
    drawVignette(context);
  }, [durationInFrames, fps, frame, height, width]);

  return (
    <canvas
      ref={canvasRef}
      width={width}
      height={height}
      style={{
        width: '100%',
        height: '100%',
        display: 'block',
        backgroundColor: '#01070c',
      }}
    />
  );
};

export const Motion: React.FC = () => {
  return (
    <AbsoluteFill style={{backgroundColor: '#01070c'}}>
      <NetworkCanvas />
    </AbsoluteFill>
  );
};
